/** biome-ignore-all lint/complexity/noUselessEscapeInRegex: Ignore. */
import { computeAccessibleName } from '../utils/computeAccessibleName';
import Constants from '../utils/constants';
import Elements from '../utils/elements';
import Lang from '../utils/lang';
import * as Utils from '../utils/utils';
import { State } from '../core/state';
import { pushResult } from '../utils/pushResult';

export default function checkDeveloper() {
  /* *************************************************************** */
  /* Error: Missing or invalid language tag.                        */
  /* *************************************************************** */
  if (!Elements.Found.Language) {
    pushResult({ test: 'META_LANG' });
  } else {
    const { valid, suggest } = Utils.validateLang(Elements.Found.Language, Lang._('LANG_CODE'));
    if (!valid) {
      if (suggest) {
        pushResult({
          test: 'META_LANG_SUGGEST',
          args: [Elements.Found.Language, suggest],
          developer: true,
        });
      } else {
        pushResult({
          test: 'META_LANG_VALID',
          args: ['html', Elements.Found.Language],
          developer: true,
        });
      }
    }
  }

  // Validate all [lang] attributes on the page.
  if (Elements.Found.LangTags?.length > 0) {
    Elements.Found.LangTags.forEach(($el) => {
      const langValue = $el.getAttribute('lang')?.trim();
      const { valid, suggest } = Utils.validateLang(langValue, Lang._('LANG_CODE'));
      if (!valid) {
        const text =
          $el.tagName === 'IMG'
            ? $el.getAttribute('alt') || ''
            : $el.nodeType === 3
              ? Utils.getText($el)
              : '';
        if (suggest) {
          pushResult({
            test: 'META_LANG_SUGGEST',
            element: $el,
            args: [langValue, suggest],
            developer: true,
            dismiss: langValue + text,
          });
        } else {
          pushResult({
            test: 'META_LANG_VALID',
            element: $el,
            args: [$el.tagName.toLowerCase(), langValue],
            developer: true,
            dismiss: langValue + text,
          });
        }
      }
    });
  }

  /* *************************************************************** */
  /*  Check for missing or potentially non-descriptive page titles.  */
  /* *************************************************************** */
  const metaTitle = document.querySelector('title:not(svg title)');
  const title = metaTitle ? Utils.getText(metaTitle).trim() : '';
  if (!title) {
    pushResult({ test: 'META_TITLE', developer: true });
  } else {
    const flag = Utils.getUndescriptiveTitleType(
      title,
      Lang.list('META_TITLE_UNDESCRIPTIVE_STRINGS'),
      Lang.list('META_TITLE_UNDESCRIPTIVE_PREFIXES'),
    );
    if (flag) {
      pushResult({
        test: 'META_TITLE_UNDESCRIPTIVE',
        type: flag,
        args: [title],
        developer: true,
        dismiss: title,
      });
    }
  }

  /* ********************************************* */
  /*  Zooming and scaling must not be disabled.    */
  /* ********************************************* */
  const content = document.querySelector('meta[name="viewport"]')?.getAttribute('content');
  if (content) {
    // Parse the content attribute to extract parameters.
    const params = content.split(',').reduce((acc, param) => {
      const [key, value] = param.split('=').map((s) => s.trim());
      acc[key] = value;
      return acc;
    }, {});

    // Check for user-scalable parameter.
    if (['no', '0'].includes(params['user-scalable'])) {
      pushResult({ test: 'META_SCALABLE', developer: true });
    }

    // Check maximum-scale parameter.
    const maxScale = parseFloat(params['maximum-scale']);
    if (!Number.isNaN(maxScale) && maxScale < 2) {
      pushResult({ test: 'META_MAX', developer: true });
    }
  }

  /* ****************************************** */
  /*  Page shouldn't automatically refresh.     */
  /* ****************************************** */
  const actuallyRefreshes = Array.from(
    document.querySelectorAll('meta[http-equiv="refresh" i]'),
  ).some((tag) => parseInt(tag.getAttribute('content'), 10) > 0);
  if (actuallyRefreshes) {
    pushResult({ test: 'META_REFRESH', developer: true });
  }

  /* *************************************************************** */
  /*  Check for duplicate IDs that are referenced by other elements. */
  /* *************************************************************** */
  if (State.option.checks.DUPLICATE_ID) {
    // Ids are unique per tree: check the document, then each detected shadow root on its own.
    // (A host's light-DOM children belong to the document tree and are checked there.)
    const scopes = [
      document.body,
      ...Array.from(
        document.querySelectorAll('[data-sa11y-has-shadow-root]'),
        (host) => host.shadowRoot,
      ),
    ];
    const exclude = Constants.Exclusions.Container.join(', ');
    scopes.forEach((scope) => {
      Utils.getReferencedDuplicateIds(scope, exclude).forEach(($el) => {
        pushResult({
          test: 'DUPLICATE_ID',
          element: $el,
          args: [$el.id],
          dismiss: `${$el.id}${$el.textContent}`,
          developer: true,
        });
      });
    });
  }

  /* ********************************************* */
  /*  Buttons must have an accessible name.        */
  /* ********************************************* */
  Elements.Found.Buttons.forEach(($el) => {
    // Ignore explicitly hidden.
    const presentation = Utils.isPresentational($el) && Utils.isDisabled($el);
    if (
      presentation ||
      Utils.isInert($el) ||
      Utils.isHiddenAndUnfocusable($el) ||
      Utils.isElementHidden($el)
    )
      return;

    // Has ARIA.
    const accName = computeAccessibleName($el);
    const buttonText = accName.replace(/['"-\.\s]+/g, '').toLowerCase();
    const textContent = Utils.getText($el);
    const dismissBase = $el.tagName + $el.id + $el.className;
    const hasAria =
      $el.querySelector(':scope [aria-labelledby], :scope [aria-label]') ||
      $el.getAttribute('aria-labelledby') ||
      $el.getAttribute('aria-label');
    const hasAriaLabelledby =
      $el.querySelector(':scope [aria-labelledby]') || $el.getAttribute('aria-labelledby');

    // Button doesn't have an accessible name.
    if (buttonText.length === 0 || !Constants.Global.unpronounceablePattern.test(buttonText)) {
      if (hasAriaLabelledby) {
        pushResult({
          test: 'BTN_EMPTY_LABELLEDBY',
          element: $el,
          content: Lang._('BTN_EMPTY_LABELLEDBY') + Lang._('BTN_TIP'),
          dismiss: dismissBase + accName,
          developer: true,
        });
      } else {
        pushResult({
          test: 'BTN_EMPTY',
          element: $el,
          content: Lang._('BTN_EMPTY') + Lang._('BTN_TIP'),
          dismiss: dismissBase,
          developer: true,
        });
      }
      return;
    }

    // Button must have visible label as part of their accessible name.
    const isVisibleTextInAccName = Utils.isVisibleTextInAccName($el, accName);
    if (hasAria && isVisibleTextInAccName) {
      pushResult({
        test: 'LABEL_IN_NAME',
        element: $el,
        type: 'warning',
        args: [textContent, accName],
        content: Lang._('LABEL_IN_NAME') + Lang._('ACC_NAME_TIP'),
        dismiss: dismissBase + accName,
        developer: true,
      });
    }

    // Has "button" in the accessible name.
    if (Utils.containsWord(accName, Lang._('BTN'))) {
      pushResult({
        test: 'BTN_ROLE_IN_NAME',
        element: $el,
        type: 'warning',
        args: [accName],
        content: Lang._('BTN_ROLE_IN_NAME') + Lang._('ACC_NAME_TIP') + Lang._('BTN_TIP'),
        dismiss: dismissBase + accName,
        developer: true,
      });
    }
  });

  /* ********************************************************** */
  /* <li> elements must be contained in a <ul>/<ol>/<menu>.     */
  /* ********************************************************** */
  Elements.Found.Lists.forEach(($el) => {
    if (!Utils.getCachedClosest($el, 'ul, ol, menu')) {
      const text = Utils.getText($el);
      pushResult({
        test: 'UNCONTAINED_LI',
        element: $el,
        args: [text],
        dismiss: text,
        developer: true,
      });
    }
  });

  /* ****************************************** */
  /*  Summary missing accessible name.          */
  /* ****************************************** */
  Elements.Found.Summary.forEach(($el) => {
    const details = $el.parentElement;
    const isControl =
      details?.tagName === 'DETAILS' && details.querySelector(':scope > summary') === $el;
    if (!isControl || computeAccessibleName($el).trim()) return;
    pushResult({
      test: 'SUMMARY_EMPTY',
      element: details,
      args: [details],
      content: Lang._('SUMMARY_EMPTY') + Lang._('ACC_NAME_TIP'),
      dismiss: $el.outerHTML,
      developer: true,
    });
  });

  /* ****************************************** */
  /*  No tabindex values greater than 0.        */
  /* ****************************************** */
  Elements.Found.TabIndex.forEach(($el) => {
    if ($el.tabIndex > 0) {
      pushResult({
        test: 'TABINDEX_ATTR',
        element: $el,
        dismiss: $el.tagName + $el.id + $el.className,
        developer: true,
      });
    }
  });

  /* *************************************************************** */
  /* Error: Focusable content hidden from screen readers.            */
  /* *************************************************************** */
  const flaggedForAriaHidden = new Set();
  Elements.Found.Focusable.forEach(($el) => {
    const isNativeDisabled = $el.hasAttribute('disabled') || $el.disabled === true;
    if (
      flaggedForAriaHidden.has($el) ||
      isNativeDisabled ||
      Utils.isNegativeTabindex($el) ||
      Utils.isElementHidden($el)
    ) {
      return;
    }

    const ariaHiddenContainer = Utils.getCachedClosest($el, '[aria-hidden="true"]');
    if (ariaHiddenContainer) {
      // Only push error if container is not hidden.
      const isContainerHidden = Utils.isElementHidden(ariaHiddenContainer);
      if (!isContainerHidden) {
        pushResult({
          test: 'HIDDEN_FOCUSABLE',
          element: $el,
          args: [Utils.truncateString($el.outerHTML, 100)],
          dismiss: $el.tagName + $el.id + $el.className,
          developer: true,
          margin: '0',
        });
        flaggedForAriaHidden.add($el);
      }
    }
  });

  /* *********************************************************** */
  /*  Warning: SVGs without an accessible name.                  */
  /* *********************************************************** */
  if (State.option.checks.SVG_NO_ACCESSIBLE_NAME) {
    // An SVG inside one of these is not announced as an image of its own: controls take their
    // name from their content or label (or make their children presentational), an image role
    // makes its children presentational, and a nested <svg> is part of the outer one.
    const svgContainerSelector = [
      'a[href]',
      'button',
      'label',
      'summary',
      'select',
      'option',
      'svg',
      ...[
        'link',
        'button',
        'tab',
        'menuitem',
        'menuitemcheckbox',
        'menuitemradio',
        'option',
        'switch',
        'checkbox',
        'radio',
        'treeitem',
        'img',
        'graphics-document',
        'graphics-object',
        'graphics-symbol',
      ].map((role) => `[role="${role}"]`),
    ].join(', ');

    // Sprite sheets and other SVGs that draw nothing: no rendered size (including those hidden
    // with width="0" height="0" rather than display: none), or only definitions as children.
    const drawsNothing = (svg) => {
      const { width, height } = svg.getBoundingClientRect();
      return (
        width === 0 ||
        height === 0 ||
        !svg.querySelector(':scope > :not(defs, symbol, title, desc, style, script, metadata)')
      );
    };

    Elements.Found.Svg.forEach((element) => {
      if (
        Utils.isPresentational(element) ||
        Utils.hasAriaHiddenAncestor(element) ||
        Utils.isElementHidden(element) ||
        Utils.getCachedClosest(element.parentElement, svgContainerSelector) ||
        drawsNothing(element) ||
        computeAccessibleName(element).trim()
      ) {
        return;
      }

      pushResult({
        test: 'SVG_NO_ACCESSIBLE_NAME',
        element,
        type: 'warning',
        args: [element],
        developer: true,
        dismiss: element.outerHTML,
      });
    });
  }
}
